setup=()=>{
  createCanvas(640,640)
  pg=createGraphics(width/4,height/4)
}

draw=()=> {
	t=frameCount
  pg.background(255)
  pg.loadPixels()
  for(y=pg.height;y--;){
    for(x=pg.width;x--;){  
      n=noise(x/60,y/60,t/60)*128
      x+y&n-t/2||pg.set(x,y,0)
    }
  }
  pg.updatePixels()

  translate(width/2,height/2)
  scale(2)
  for(v of [[1,1],[-1,1],[1,-1],[-1,-1]]){
    push()
    scale(v)
    image(pg,0,0)
    pop()
  }
}
